/**
 * Curated media corpus — talks, blog posts, forum posts, tweets and hubs.
 *
 * Every URL in this file was verified against a search result during curation
 * (`scripts/verify-links.ts` re-checks them on demand). Nothing here is invented:
 * if a link could not be confirmed it was left out.
 *
 * This is the non-arXiv half of the corpus atlas. The arXiv half lives in
 * `corpus.papers.json`, generated by `scripts/harvest-arxiv.ts`.
 */
import type { CorpusEntry } from "@repo/core";

const talk = (
  id: string,
  title: string,
  speaker: string,
  year: number,
  url: string,
  tags: readonly string[],
  why: string
): CorpusEntry => ({
  id,
  kind: "talk",
  title,
  authors: [speaker],
  year,
  venue: speaker,
  url,
  oneLiner: why,
  tags,
  source: "curated-2026-10"
});

const post = (
  id: string,
  title: string,
  author: string,
  year: number,
  url: string,
  tags: readonly string[],
  why: string
): CorpusEntry => ({
  id,
  kind: "post",
  title,
  authors: [author],
  year,
  venue: hostOf(url),
  url,
  oneLiner: why,
  tags,
  source: "curated-2026-10"
});

const tweet = (
  id: string,
  handle: string,
  statusId: string,
  year: number,
  tags: readonly string[],
  why: string
): CorpusEntry => ({
  id,
  kind: "post",
  title: `@${handle} — ${why.slice(0, 72)}`,
  authors: [`@${handle}`],
  year,
  venue: "X (Twitter)",
  url: `https://x.com/${handle}/status/${statusId}`,
  oneLiner: why,
  tags,
  source: "curated-2026-10"
});

function hostOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return "unknown";
  }
}

